        'using_step1' => '<strong>ഒരു നടപടിക്രമം ചേർക്കുക</strong> - പേര് അല്ലെങ്കിൽ കീവേഡ് പ്രകാരം തിരയുക, <strong>ചേർക്കുക</strong> അമർത്തുക. ഒരേ ടിക്കറ്റിൽ ഒന്നിലധികം ചേർക്കാം.',
        'using_step2' => '<strong>മികച്ച പൊരുത്തം</strong> - ഒരു ടെംപ്ലേറ്റിന്റെ കീവേഡുകൾ ടിക്കറ്റുമായി പൊരുത്തപ്പെട്ടാൽ, ചോദിക്കാതെ തന്നെ FreeITSM അത് മുകളിൽ വാഗ്ദാനം ചെയ്യുന്നു. കീവേഡുകൾ ഇതിനുവേണ്ടിയാണ്.',
        'using_step3' => 'നിങ്ങൾ ചെയ്യുമ്പോൾ <strong>ഘട്ടങ്ങൾ ടിക് ചെയ്യുക</strong>. ഓരോ ടിക്കും ആരാണ്, എപ്പോഴാണ് എന്ന് രേഖപ്പെടുത്തുന്നു; ഒരു മൂല്യം ചോദിക്കാൻ സജ്ജമാക്കിയ ഘട്ടം ടിക് ചെയ്യുമ്പോൾ അതിന് ചോദിക്കുന്നു.',
        'using_step4' => 'ഒരു ഘട്ടം പൂർത്തിയാകുകയോ വീണ്ടും തുറക്കുകയോ ചെയ്യുമ്പോഴെല്ലാം <strong>ടിക്കറ്റിൽ ഒരു കുറിപ്പ് ചേർക്കുന്നു</strong>, അതിനാൽ ടിക്കറ്റിന്റെ ചരിത്രം സ്വന്തമായി കഥ പറയുന്നു - മാസങ്ങൾക്ക് ശേഷം ഉപകാരപ്രദം, ജോലി പരിശോധിക്കുന്ന ആർക്കും ഉപകാരപ്രദം.',
        'using_step5' => '<strong>നീക്കം ചെയ്യുക</strong> ടിക്കറ്റിൽ നിന്ന് ഒരു നടപടിക്രമം എടുത്തുകളയുന്നു. ഇത് ആദ്യം ചോദിക്കുന്നു, കാരണം ടിക്കുകളും അതോടൊപ്പം പോകുന്നു.',
        'closing_heading' => 'നിർബന്ധിത ഘട്ടങ്ങളും ടിക്കറ്റ് അടയ്ക്കലും',
        'closing_intro' => 'ഒരു നിർബന്ധിത ഘട്ടം അത് ഒഴിവാക്കുമ്പോൾ എന്തെങ്കിലും സംഭവിച്ചാൽ മാത്രമേ അടയാളപ്പെടുത്തുന്നത് മൂല്യമുള്ളൂ. എന്ത് സംഭവിക്കും എന്നത് നിങ്ങളുടെ തിരഞ്ഞെടുപ്പാണ്, <strong>ടിക്കറ്റുകൾ &rarr; ക്രമീകരണങ്ങൾ &rarr; ചെക്ക്‌ലിസ്റ്റുകൾ</strong>-ൽ.',
        'closing_warn_title' => 'മുന്നറിയിപ്പ്',
        'closing_warn_desc' => 'ടിക്കറ്റ് അടയുന്നു, ഘട്ടങ്ങൾ ബാക്കിയുള്ളപ്പോൾ അത് അടച്ചു എന്ന് ഒരു ആന്തരിക കുറിപ്പ് രേഖപ്പെടുത്തുന്നു - ഏതൊക്കെ, ആരാണ് അടച്ചത്, വെബ് ഇന്റർഫേസിൽ നിന്നോ API-യിൽ നിന്നോ ചെയ്തതെന്നും. സ്ഥിരസ്ഥിതി, മിക്ക ഡെസ്കുകൾക്കും ശരിയായ ക്രമീകരണം: അനലിസ്റ്റിന് സാധാരണയായി ഒരു കാരണമുണ്ടാകും, കുറിപ്പ് അതിനർത്ഥം ആർക്കും അത് ഓർക്കേണ്ടതില്ല എന്നാണ്.',
        'closing_block_title' => 'തടയുക',
        'closing_block_desc' => 'നിർബന്ധിത ഘട്ടങ്ങൾ പൂർത്തിയാകുന്നത് വരെ അടയ്ക്കൽ നിരസിക്കപ്പെടുന്നു, സന്ദേശം അവയെ പേരെടുത്ത് പറയുന്നു. നടപടിക്രമം തന്നെയാണ് കാതൽ എന്നിടത്ത് ഇത് തിരഞ്ഞെടുക്കുക - ഒരു നിയന്ത്രിത പ്രക്രിയ, അല്ലെങ്കിൽ ഒരു ഘട്ടം നഷ്ടമായാൽ ആക്സസ് സജീവമായി തുടരുന്ന ഒരു വിട്ടുപോകുന്നയാളുടെ ചെക്ക്‌ലിസ്റ്റ്.',
        'closing_enforced' => '<strong>നിങ്ങൾ എന്ത് തിരഞ്ഞെടുത്താലും അത് ടിക്കറ്റ് അടയ്ക്കാവുന്ന എല്ലായിടത്തും നടപ്പാക്കപ്പെടുന്നു</strong>, നിങ്ങളുടെ മുന്നിലുള്ള ബട്ടണിൽ മാത്രമല്ല: ബൾക്ക് പ്രവർത്തനങ്ങൾ, REST API, വർക്ക്ഫ്ലോ ഓട്ടോമേഷൻ എല്ലാം ഇത് അനുസരിക്കുന്നു. ഒരു സ്ക്രീനിൽ മാത്രം ജീവിക്കുന്ന ഒരു നിയമം ഒരു നിയമമല്ല, ചുറ്റിനടക്കാവുന്ന ഒരു ഗേറ്റ് ഇല്ലാത്ത നിയന്ത്രണം റിപ്പോർട്ട് ചെയ്യുന്നു.',
        'settings_heading' => 'ക്രമീകരണങ്ങൾ',
        'settings_intro' => 'രണ്ട് സ്ക്രീനുകൾ പ്രധാനമാണ്, അവ വ്യത്യസ്ത ജോലികൾ ചെയ്യുന്നു.',
        'settings_mod_title' => 'ചെക്ക്‌ലിസ്റ്റുകൾ &rarr; ക്രമീകരണങ്ങൾ',
        'settings_mod_desc' => '<strong>വിഭാഗങ്ങൾ</strong> ടെംപ്ലേറ്റുകളെ ഗ്രൂപ്പ് ചെയ്യുകയും അവയുടെ പിൽ നിറം നൽകുകയും ചെയ്യുന്നു. <strong>റോളുകൾ</strong> ഒരു ഘട്ടത്തിലെ "നിർദ്ദിഷ്ട റോൾ" പട്ടിക നിറയ്ക്കുന്നു. രണ്ടും ഇല്ലാതാക്കുന്നതിന് മുമ്പ് എത്ര ഘട്ടങ്ങളോ ടെംപ്ലേറ്റുകളോ ഒരു എൻട്രി ഉപയോഗിക്കുന്നു എന്ന് കാണിക്കുന്നു. <strong>ഇടത് പാനൽ</strong> ഒരു അക്കൗണ്ട്-തിരിച്ചുള്ള മുൻഗണനയാണ്: ടെംപ്ലേറ്റ് സൈഡ്ബാർ എപ്പോഴും ദൃശ്യമായി സൂക്ഷിക്കുക, അല്ലെങ്കിൽ ഹോവറിൽ ദൃശ്യമാകാൻ അനുവദിക്കുക.',
        'settings_tick_title' => 'ടിക്കറ്റുകൾ &rarr; ക്രമീകരണങ്ങൾ &rarr; ചെക്ക്‌ലിസ്റ്റുകൾ',
        'settings_tick_desc' => 'നിർബന്ധിത ഘട്ടങ്ങൾ ബാക്കിയുള്ള ഒരു ടിക്കറ്റ് അടയ്ക്കുമ്പോൾ മുന്നറിയിപ്പ് നൽകുക അല്ലെങ്കിൽ തടയുക. ഇത് ടിക്കറ്റുകൾ അടയ്ക്കുന്നതിനെക്കുറിച്ചുള്ള ഒരു നിയമമായതിനാൽ ഇവിടെയല്ല, ടിക്കറ്റ് ക്രമീകരണങ്ങളോടൊപ്പമാണ് ഇത് ഇരിക്കുന്നത്, ആരെങ്കിലും അത് നോക്കുന്നിടത്ത്.',
        'settings_demo' => '<strong>സിസ്റ്റം &rarr; ഡെമോ ഡാറ്റ</strong> അഞ്ച് യാഥാർത്ഥ്യബോധമുള്ള നടപടിക്രമങ്ങൾ വിതയ്ക്കും - ഓൺബോർഡിംഗ്, ഓഫ്ബോർഡിംഗ്, സെർവർ ഡീകമ്മീഷനിംഗ്, VPN ട്രബിൾഷൂട്ടിംഗ്, ഒരു ഫയർവാൾ മാറ്റം - അതിനാൽ എഴുതുന്നതിന് മുമ്പ് മൊഡ്യൂൾ പ്രവർത്തിക്കുന്നത് നിങ്ങൾക്ക് കാണാം. ഡെമോ ഡാറ്റ നീക്കം ചെയ്യുന്നത് കൃത്യമായി അവയെ മാത്രം നീക്കം ചെയ്യുന്നു, നിങ്ങൾ എഴുതിയത് ഒന്നും അല്ല.',
        'tips_heading' => 'നുറുങ്ങുകൾ',
        'tip_one_action_title' => 'ഓരോ ഘട്ടത്തിനും ഒരു പ്രവർത്തനം',
        'tip_one_action_body' => 'ഒരു ഘട്ടത്തിന് അതെ അല്ലെങ്കിൽ ഇല്ല എന്ന് ഉത്തരം നൽകാനാവില്ലെങ്കിൽ, അത് രണ്ട് ഘട്ടങ്ങളാണ്. ഒരു നടപടിക്രമം ഉപയോഗിക്കപ്പെടുമോ അവഗണിക്കപ്പെടുമോ എന്ന് തീരുമാനിക്കുന്ന ഒരേയൊരു കാര്യമാണിത്.',
        'tip_keywords_title' => 'കീവേഡുകൾക്കായി ഒരു മിനിറ്റ് ചെലവഴിക്കുക',
        'tip_keywords_body' => 'ആർക്കും കണ്ടെത്താനാവാത്ത ഒരു നടപടിക്രമം ആരും പിന്തുടരാത്ത ഒരു നടപടിക്രമമാണ്. നിങ്ങൾ ഉപയോഗിക്കുന്ന വാക്കുകളല്ല, അഭ്യർത്ഥിക്കുന്ന ആൾ ഉപയോഗിക്കുന്ന വാക്കുകൾ ചേർക്കുക - "cannot get in" എന്ന്, "authentication failure" എന്നല്ല.',
        'tip_mandatory_title' => 'നിർബന്ധിതത്തിൽ പിശുക്ക് കാണിക്കുക',
        'tip_mandatory_body' => 'എല്ലാം നിർബന്ധിതമായി അടയാളപ്പെടുത്തിയാൽ ആളുകൾ വായിക്കാതെ തന്നെ മുന്നറിയിപ്പിലൂടെ അടയ്ക്കാൻ പഠിക്കും. പ്രധാനപ്പെട്ട മൂന്ന് അടയാളപ്പെടുത്തിയാൽ മുന്നറിയിപ്പിന് ഇപ്പോഴും അർത്ഥമുണ്ടാകും.',
        'tip_edit_title' => 'ടിക്കറ്റല്ല, ടെംപ്ലേറ്റ് മെച്ചപ്പെടുത്തുക',
        'tip_edit_body' => 'ജോലിക്കിടയിൽ ആരെങ്കിലും ഒരു നഷ്ടമായ ഘട്ടം കണ്ടെത്തിയാൽ, അത് ടെംപ്ലേറ്റിലും ചേർക്കുക. ചേർത്ത ചെക്ക്‌ലിസ്റ്റുകൾ പകർപ്പുകളാണ്, അതിനാൽ നിങ്ങളുടെ മുന്നിലുള്ള ടിക്കറ്റ് അതിന്റെ ഘട്ടങ്ങൾ സൂക്ഷിക്കുന്നു, ഭാവിയിലെ ഓരോ ടിക്കറ്റിനും മെച്ചപ്പെട്ട നടപടിക്രമം ലഭിക്കുന്നു.',
    ],
];
